#include <stdio.h>

int main(void) {
    int n = 5;
    int sum = 0;
    for (int i = 1; i <= n; ++i) {
        sum += i;
    }
    printf("sum=%d\n", sum);
    int remaining = 3;
    while (remaining > 0) {
        printf("%d ", remaining);
        --remaining;
    }
    puts("");
    return 0;
}
